import { useState } from "react";
import * as pdfMake from "pdfmake/build/pdfmake";

// Gắn font mặc định vào pdfmake (bắt buộc)
// (pdfMake as any).vfs = (pdfFonts as any).pdfMake.vfs;

// Hàm tạo nội dung PDF
const createPdfDocDefinition = (_config: {
  headerInfo: any;
  isoInfo: any;
  title: string;
  headerFields: Array<{
    label: string;
    type: string;
    value?: any;
  }>;
  tableColumns: Array<{
    children: any;
    title: string;
    dataIndex: string;
  }>;
  footerNotes: string[];
  signatures: Array<{
    label: string;
    signer: string;
  }>;
}) => {
  return {
    pageSize: "A4",
    pageMargins: [40, 60, 40, 60],
    content: [
      {
        columns: [
          {
            image:
              "data:image/png;base64,",
            width: 150,
          },
          //   {
          //     text: "CÔNG TY CỔ PHẦN THÉP HÒA PHÁT DUNG QUẤT",
          //     alignment: "center",
          //     bold: true,
          //     fontSize: 6,
          //     margin: [0, 15, 0, 0],
          //   },
          {
            text: "BM.06/QT.05.11\nNgày hiệu lực: 16/05/2025\nLần sửa đổi: 01",
            alignment: "right",
            fontSize: 9,
          },
          //   {
          //     text: config.title,
          //     alignment: "center",
          //     fontSize: 14,
          //     bold: true,
          //     margin: [0, 10, 0, 0],
          //   },
        ],
      },
      { text: "\nBIÊN BẢN GIAO NHẬN PHÔI NÓNG", style: "title" },
      { text: "\n\n" },
      {
        table: {
          headerRows: 1,
          widths: ["auto", "*", "auto", "auto", "auto"],
          body: [
            [
              { text: "STT", bold: true, alignment: "center" },
              { text: "Mác thép", bold: true, alignment: "center" },
              { text: "Kích thước", bold: true, alignment: "center" },
              { text: "Số thanh", bold: true, alignment: "center" },
              { text: "Khối lượng (tấn)", bold: true, alignment: "center" },
            ],
            ["1", "CT3", "165x12M", "56", "2.573"],
            ["2", "CT5", "165x12M", "50", "2.573"],
          ],
        },
        layout: "lightHorizontalLines",
      },
      { text: "\nGhi chú:", bold: true },
      { text: "Tất cả phôi đạt chỉ tiêu, đủ điều kiện đưa vào cán." },
      { text: "\n\n\n" },
      {
        columns: [
          {
            text: "P.QLCL\n\n\n__________________\nBùi Văn Thành",
            alignment: "center",
          },
          {
            text: "NM.HRC1\n\n\n__________________\nPhạm Văn Nhân",
            alignment: "center",
          },
        ],
      },
    ],
    styles: {
      title: {
        alignment: "center",
        fontSize: 16,
        bold: true,
      },
    },
  };
};
interface DynamicBMFormProps {
  config: {
    headerInfo: any;
    isoInfo: any;
    title: string;
    headerFields: Array<{
      label: string;
      type: string;
      value?: any;
    }>;
    tableColumns: Array<{
      children: any;
      title: string;
      dataIndex: string;
    }>;
    footerNotes: string[];
    signatures: Array<{
      label: string;
      signer: string;
    }>;
  };
}
// Component React hiển thị PDF
export default function PdfMakeExample({ config }: DynamicBMFormProps) {
  const [pdfUrl, setPdfUrl] = useState<string>("");

  // Xem trước PDF (dạng blob)
  const handlePreview = () => {
    const docDef = createPdfDocDefinition(config);
    const pdfDocGenerator = (pdfMake as any).createPdf(docDef);
    pdfDocGenerator.getBlob((blob: Blob) => {
      const url = URL.createObjectURL(blob);
      setPdfUrl(url);
    });
  };

  // Tải PDF trực tiếp
  const handleDownload = () => {
    const docDef = createPdfDocDefinition(config);
    (pdfMake as any).createPdf(docDef).download("BienBanGiaoNhanPhoiNong.pdf");
  };

  return (
    <div style={{ padding: 20 }}>
      <h3>📄 Demo pdfmake trong React</h3>
      <button
        onClick={handlePreview}
        style={{
          padding: "8px 16px",
          marginRight: 8,
          background: "#1677ff",
          color: "#fff",
          border: "none",
          borderRadius: 4,
        }}
      >
        🔍 Xem trước PDF
      </button>
      <button
        onClick={handleDownload}
        style={{
          padding: "8px 16px",
          background: "#00b96b",
          color: "#fff",
          border: "none",
          borderRadius: 4,
        }}
      >
        ⬇️ Tải PDF
      </button>

      {pdfUrl && (
        <iframe
          src={pdfUrl}
          title="PDF Preview"
          style={{
            width: "100%",
            height: "90vh",
            marginTop: 16,
            border: "1px solid #ccc",
          }}
        />
      )}
    </div>
  );
}
